tools.example:
CHANGE LAYER TOP;
ROUTE 0.3mm      # click an airwire to route it on Top
# CAM: "layers": [1, 17, 18]  ->  copper_top.gbr

DRC *   # Layers tab: Setup (1*2+15*16)
CHANGE LAYER 2;
POLYGON GND 0.3mm (0 0) (100 0) (100 80) (0 80) (0 0);

GRID MM 1;
CHANGE LAYER DIMENSION;
LINE 0 (0 0) (100 0) (100 80) (0 80) (0 0);

LAYER 101 SAMPLE;
LAYER 53 tSomething;
LAYER 54 bSomething;
LAYER ?? -103;

# place two parts and connect them
GRID MM 1;
ADD R-EU_0204/7@rcl R1 R0 (10 10);
ADD C-EU025-024X044@rcl C1 R90 (20 10);
NET N$1 (12.54 10) (20 7.46);
WRITE;

#usage "<b>List elements</b>"
output("parts.csv", "wt") {
  board(B) {
    B.elements(E) printf("%s;%s;%s\n", E.name, E.value, E.package.name);
  }
}

